// Format: <service>:<jira_url_or_key> [optional additional context]
// Additional context can follow the ticket key on the same line or on new lines.
// e.g. ibe:IBE-1153
//      Stack trace: TypeError at line 45
//      Only happens for hotel ID 123
const input = $json.chatInput.trim();
const colonIdx = input.indexOf(':');
if (colonIdx === -1) {
  throw new Error('Format: <service>:<jira_url_or_key>  e.g. ibe:IBE-1153');
}

const service = input.substring(0, colonIdx).trim().toLowerCase();
const rest = input.substring(colonIdx + 1).trim();

const match = rest.match(/([A-Z]+-\d+)/);
if (!match) {
  throw new Error('Could not find a Jira issue key in: ' + rest);
}

const issueKey = match[1];
// Everything after the issue key (or URL containing it) is additional context
const afterKey = rest.substring(rest.indexOf(issueKey) + issueKey.length).trim();
// Strip leading URL path remnants like "/browse/" fragments
const additionalContext = afterKey.replace(/^\/[^\s]*/, '').trim();

return { service, issueKey, additionalContext };

function extractText(node) {
  if (!node) return '';
  if (node.type === 'text') return node.text || '';
  if (node.content) return node.content.map(extractText).join(' ');
  return '';
}

const issue = $('Fetch Jira Issue').item.json;
const { service, additionalContext } = $('Extract Issue Key').item.json;
const issueKey = issue.key;
const summary = issue.fields.summary;
const descAdf = issue.fields.description;
const description = descAdf ? extractText(descAdf).trim() : 'No description provided.';

const parts = [
  `${service}: You are performing Root Cause Analysis (RCA) for a production bug. Analyse the codebase carefully.`,
  ``,
  `Ticket: ${issueKey}`,
  `Summary: ${summary}`,
  ``,
  `Description:`,
  description,
];

if (additionalContext) {
  parts.push(``, `Additional context provided by reporter:`, additionalContext);
}

parts.push(
  ``,
  `Based on the codebase, answer:`,
  `1. Which files and functions are involved in the flow described above?`,
  `2. Where exactly is the root cause in the code (file path and function)?`,
  `3. What is the precise fix with a code snippet?`
);

return { issueKey, service, message: parts.join('\n') };

function mdToJira(text) {
  return text
    .replace(/```(\w+)\n([\s\S]*?)```/g, '{code:$1}\n$2{code}')
    .replace(/```\n?([\s\S]*?)```/g, '{code}\n$1{code}')
    .replace(/`([^`\n]+)`/g, '{{$1}}')
    .replace(/\*\*(.+?)\*\*/g, '*$1*')
    .replace(/^### (.+)$/gm, 'h3. $1')
    .replace(/^## (.+)$/gm,  'h2. $1')
    .replace(/^# (.+)$/gm,   'h1. $1')
    .replace(/^\d+\. (.+)$/gm, '# $1')
    .replace(/^[ \t]*[-*] (.+)$/gm, '* $1')
    .replace(/^---+$/gm, '----')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const rcaText = $('Ask codebot').item.json.response;
const issueKey = $('Build RAG Query').item.json.issueKey;

const jiraBody = [
  'h2. \uD83E\uDD16 AI-Generated Root Cause Analysis',
  '',
  mdToJira(rcaText),
  '',
  '----',
  '_Generated automatically by codebot. Please review before acting on it._'
].join('\n');

return { issueKey, rcaText, jiraBody };

const issueKey = $('Format RCA Comment').item.json.issueKey;
const rcaText = $('Format RCA Comment').item.json.rcaText;
return { output: `\u2705 RCA posted to ${issueKey}.\n\n${rcaText}` };
